const pick=<T,>(items:T[])=>items[Math.floor(Math.random()*items.length)];
const createIncident=(previousPlace=""):Scenario=>{let recent:string[]=[];if(typeof window!=="undefined")try{recent=JSON.parse(localStorage.getItem("leitstelle-incident-history")??"[]")}catch{}let created:Scenario=scenarios[0],signature="";for(let attempt=0;attempt<80;attempt++){const choices=scenarios.filter(s=>s.place!==previousPlace),base=pick(choices.length?choices:scenarios),profile=incidentProfiles[base.code],title=profile?pick(profile.titles):base.title,report=profile?pick(profile.reports):base.detail,danger=profile?pick(profile.dangers):base.danger,caller=base.caller==="Brandmeldeanlage"||base.caller==="Rezeption"?base.caller:pick(callerNames),extra=pick(circumstances),condition=pick(weather);created={...base,title,caller,danger,detail:`${report} ${extra} ${condition}`};signature=`${created.place}|${created.title}|${extra}|${condition}`;if(!recent.includes(signature))break}if(typeof window!=="undefined")localStorage.setItem("leitstelle-incident-history",JSON.stringify([signature,...recent.filter(item=>item!==signature)].slice(0,250)));return created};
const distance=(a:[number,number],b:[number,number])=>{const x=(a[1]-b[1])*75,y=(a[0]-b[0])*111;return Math.sqrt(x*x+y*y)};
const preferredAlarmVoice=()=>{const german=window.speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith("de")),preference=["google deutsch","katja","amala","seraphina","vicki","petra","marlene","anna"];return preference.map(name=>german.find(v=>v.name.toLowerCase().includes(name)&&/natural|premium|enhanced|online|google/.test(v.name.toLowerCase()))).find(Boolean)??preference.map(name=>german.find(v=>v.name.toLowerCase().includes(name))).find(Boolean)??german.find(v=>v.lang.toLowerCase()==="de-at")??german[0]};
