const pointOnRoute=(points:[number,number][]|undefined,p:number,start:[number,number],end:[number,number])=>{const route=points?.length?points:[start,end],position=Math.max(0,Math.min(100,p))/100*(route.length-1),i=Math.min(route.length-2,Math.floor(position)),f=position-i;return[route[i][0]+(route[i+1][0]-route[i][0])*f,route[i][1]+(route[i+1][1]-route[i][1])*f] as [number,number]};
