 const ring=()=>{const AudioCtx=window.AudioContext||(window as typeof window&{webkitAudioContext:typeof AudioContext}).webkitAudioContext;if(!AudioCtx)return;const ctx=audioContext.current??new AudioCtx();audioContext.current=ctx;if(ctx.state==="suspended")ctx.resume();[0,.14].forEach(delay=>{[425,480].forEach(freq=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(0,ctx.currentTime+delay);gain.gain.linearRampToValueAtTime(.055,ctx.currentTime+delay+.02);gain.gain.setValueAtTime(.055,ctx.currentTime+delay+.11);gain.gain.linearRampToValueAtTime(0,ctx.currentTime+delay+.14);osc.connect(gain).connect(ctx.destination);osc.start(ctx.currentTime+delay);osc.stop(ctx.currentTime+delay+.15)})})};
 useEffect(()=>{if(ringTimer.current){clearInterval(ringTimer.current);ringTimer.current=null}if(phase==="call"&&!localSignedOut){ring();ringTimer.current=setInterval(ring,2600)}return()=>{if(ringTimer.current){clearInterval(ringTimer.current);ringTimer.current=null}}},[phase,incidentNumber,localSignedOut]);
 useEffect(()=>{const unlock=()=>{if(audioContext.current?.state==="suspended")audioContext.current.resume();if(phase==="call")ring()};document.addEventListener("pointerdown",unlock,{once:true});return()=>document.removeEventListener("pointerdown",unlock)},[phase]);
 useEffect(()=>{if(phase!=="alerted"&&phase!=="returning")return;const drive=setInterval(()=>setProgress(p=>{const values=Object.values(p);if(phase==="alerted"&&values.every(v=>v>=100)||phase==="returning"&&values.every(v=>v<=0))return p;return Object.fromEntries(Object.entries(p).map(([id,value])=>[id,phase==="alerted"?Math.min(100,value+.55):Math.max(0,value-.55)]))}),1000);return()=>clearInterval(drive)},[phase]);
 const ranked=useMemo(()=>units.map(u=>({...u,km:distance(u.coords,incident.coords),eta:Math.max(3,Math.round(distance(u.coords,incident.coords)*1.25))})).sort((a,b)=>a.km-b.km),[incident]);
