 const activeStatus=(entry:ActiveIncident)=>{const seconds=(activeClock-entry.startedAt)/1000;return seconds<entry.driveSeconds?"STATUS 3 · ANFAHRT":seconds<entry.driveSeconds+entry.sceneSeconds?"STATUS 4 · EINSATZORT":seconds<entry.driveSeconds+entry.sceneSeconds+entry.transportSeconds&&entry.hospital?`PATIENTENTRANSPORT · ${entry.hospital}`:"STATUS 1 · FREI AUF RÜCKFAHRT"};
