 useEffect(()=>{if(phase!=="alerted"||!selected.length)return;if(selected.every(id=>(progress[id]??0)>=100)){const returnCall=setTimeout(()=>setPhase("returning"),sceneDuration(incident.code)*1000);return()=>clearTimeout(returnCall)}},[phase,progress,selected,incident.code]);
